    /// <summary>
    /// Renders one icon.
    /// <para>
    /// A name nothing recognizes renders nothing rather than throwing: a missing glyph is a
    /// blemish, and a screen that will not render at all because somebody mistyped an icon name
    /// is an outage.
    /// </para>
    /// </summary>
    /// <param name="name">The Phosphor name, such as <c>magnifying-glass</c>.</param>
    /// <param name="size">The square size in pixels.</param>
    /// <returns>The inline SVG.</returns>
    public static IHtmlContent Render(string name, int size = 16)
    {
        if (name is null || !Paths.TryGetValue(name, out string? inner))
        {
            return HtmlString.Empty;
        }

        string encoded = HtmlEncoder.Default.Encode(name);
        string box = size.ToString(CultureInfo.InvariantCulture);

        return new HtmlString(
            $"<svg class=\"ico\" width=\"{box}\" height=\"{box}\" viewBox=\"0 0 256 256\" "
            + $"fill=\"currentColor\" aria-hidden=\"true\" focusable=\"false\" "
            + $"data-icon=\"{encoded}\">{inner}</svg>");
    }

    /// <summary>Whether the set has an icon by this name.</summary>
    /// <param name="name">The Phosphor name.</param>
    /// <returns>True when it does.</returns>
    public static bool Has(string name) => name is not null && Paths.ContainsKey(name);
}
